import math

def nyquist(bandwidth_hz, levels):
    return 2 * bandwidth_hz * math.log2(levels)

def shannon(bandwidth_hz, snr_db):
    snr = 10 ** (snr_db / 10)
    return bandwidth_hz * math.log2(1 + snr)

print("Nyquist, 3 kHz, 4 levels:", nyquist(3000, 4), "bps")
print("Shannon, 3 kHz, 35 dB: %.0f bps" % shannon(3000, 35))
print("Shannon, 20 MHz Wi-Fi channel, 25 dB: %.1f Mbps" % (shannon(20e6, 25) / 1e6))

