class Switch:
    def __init__(self, ports):
        self.ports = ports
        self.table = {}

    def receive(self, src, dst, port):
        self.table[src] = port
        if dst != "BROADCAST" and dst in self.table:
            out = [self.table[dst]]
            action = "forward"
        else:
            out = [p for p in self.ports if p != port]
            action = "flood"
        print(f"{src}->{dst} on port {port}: {action} to {out}")

sw = Switch([1, 2, 3, 4])
sw.receive("A", "B", 1)
sw.receive("B", "A", 2)
sw.receive("A", "B", 1)
sw.receive("C", "BROADCAST", 3)
print("MAC table:", sw.table)

def crc_remainder(data, gen):
    r = len(gen) - 1
    bits = list(data + "0" * r)
    for i in range(len(data)):
        if bits[i] == "1":
            for j in range(len(gen)):
                bits[i + j] = "0" if bits[i + j] == gen[j] else "1"
    return "".join(bits[-r:])

data, gen = "11010011101100", "1011"
rem = crc_remainder(data, gen)
frame = data + rem
print("remainder:", rem, "frame:", frame)

def check(frame, gen):
    return crc_remainder(frame[: -(len(gen) - 1)], gen) == frame[-(len(gen) - 1):]

print("intact frame ok?", check(frame, gen))
bad = frame[:3] + ("1" if frame[3] == "0" else "0") + frame[4:]
print("damaged frame ok?", check(bad, gen))

