def to_int(s):
    a, b, c, d = map(int, s.split("."))
    return (a << 24) | (b << 16) | (c << 8) | d

def to_str(n):
    return ".".join(str((n >> s) & 255) for s in (24, 16, 8, 0))

ip, prefix = to_int("192.168.10.77"), 26
mask = (0xFFFFFFFF << (32 - prefix)) & 0xFFFFFFFF
net = ip & mask
bcast = net | (~mask & 0xFFFFFFFF)
print(to_str(mask), to_str(net), to_str(bcast))

import math
def fspl_db(distance_m, freq_mhz):
    # free-space path loss
    return 20 * math.log10(distance_m / 1000) + 20 * math.log10(freq_mhz) + 32.44

for f in (2400, 5000, 6000):
    print(f, "MHz at 10 m:", round(fspl_db(10, f), 1), "dB loss")

