import math

def fspl_db(distance_m, freq_mhz):
    return 20 * math.log10(distance_m / 1000) + 20 * math.log10(freq_mhz) + 32.44

tx_power_dbm = 20  # typical AP transmit power
for band in (2400, 5000, 6000):
    for d in (1, 10, 30):
        rx = tx_power_dbm - fspl_db(d, band)
        quality = "excellent" if rx > -50 else "good" if rx > -67 else "fair" if rx > -75 else "poor"
        print(f"{band} MHz, {d:>2} m: {rx:6.1f} dBm ({quality}, free space, no walls)")

